import java.util.*;
import net.sf.l2j.gameserver.GameServer;
import net.sf.l2j.gameserver.model.World;
import net.sf.l2j.gameserver.model.actor.Player;
import net.sf.l2j.gameserver.model.actor.instance.Monster;
import net.sf.l2j.gameserver.model.actor.player.Experience;
import net.sf.l2j.gameserver.model.location.Location;
import dev.l2j.autobots.autofarm.AutofarmManager;

/** Narrow observed level-20 base-class owner: unchanged coins, gear, skills, potions and scroll; real road/XP. */
public class BaseClassTravelBudgetVerify extends NoviceTravelTopupVerify {
 @SuppressWarnings("unchecked") public static void main(String[] args){try{
  if(!"yes".equals(System.getenv("L2_MOVEMENT_ISOLATED")))throw new IllegalStateException();GameServer.main(new String[0]);Object m=singleton("offlinelife.OfflineFarmManager");invoke(member(m,"travelTask").get(m),"cancel");invoke(member(AutofarmManager.INSTANCE,"onUpdateTask").get(AutofarmManager.INSTANCE),"cancel");gear=singleton("population.economy.Gear");market=singleton("population.economy.Market");travel=singleton("population.economy.GatekeeperTravel");errands=singleton("population.economy.Errands");
  Player p=Player.restore(268486152);check(p!=null&&p.getLevel()==20&&p.getClassId().level()==0&&p.getExp()==857473,"narrow snapshot restores the actual unpromoted level-20 owner");p.setClient((net.sf.l2j.gameserver.network.GameClient)Class.forName("dev.l2j.autobots.offlinelife.DetachedClient").getConstructor(Player.class).newInstance(p));invoke(AutofarmManager.INSTANCE,"onEnterWorld",p);World.getInstance().addPlayer(p);p.setOnlineStatus(true,true);p.spawnMe(p.getX(),p.getY(),p.getZ());p.onPlayerEnter();Map<Integer,Player> farmers=(Map<Integer,Player>)member(m,"farming").get(m);farmers.put(p.getObjectId(),p);invoke(m,"openJournal",p);invoke(AutofarmManager.INSTANCE,"quiesce",p);p.setAccessLevel(0);p.setIsInvul(false);check(p.getX()==12104&&p.getY()==16824&&p.getAdena()==2205,"observed origin and actual wallet are unchanged");check((Integer)invoke(singleton("population.economy.Healing"),"count",p)==10&&p.getInventory().getInventoryItemCount(736,-1)==1,"observed ten heals and own escape scroll remain carried");check(fare((List<?>)invoke(travel,"offers",p),890),"already prepared base class can pay a useful real fare after level 20");
  if(Arrays.asList(args).contains("--plan-only")){System.out.println("BASE CLASS TRAVEL BUDGET PLAN ALL PASSED");System.exit(0);}
  Set<Integer> quotedFares=new HashSet<>();for(Object offer:(List<?>)invoke(travel,"offers",p))quotedFares.add((Integer)invoke(offer,"getPrice"));int actualFare=0;long started=System.currentTimeMillis(),xp=p.getExp(),reported=started,deadline=started+600000;int cash=p.getAdena();long scroll=p.getInventory().getInventoryItemCount(736,-1);for(String f:new String[]{"lessonCheckedAt","equipmentCheckedAt"})((Map<Integer,Long>)member(m,f).get(m)).put(p.getObjectId(),started+3600000);Location origin=location(p),goal=null;boolean arrived=false,paid=false,departed=false;invoke(m,"goHunting",p);
  while(System.currentTimeMillis()<deadline&&!p.isDead()&&p.getExp()<=xp){invoke(m,"tick");Object route=((Map<?,?>)member(m,"traveling").get(m)).get(p.getObjectId());if(route!=null&&invoke(route,"getTrip").toString().equals("TO_SPOT"))goal=new Location((Integer)invoke(route,"getTargetX"),(Integer)invoke(route,"getTargetY"),(Integer)invoke(route,"getTargetZ"));if(!paid&&quotedFares.contains(cash-p.getAdena())){paid=true;actualFare=cash-p.getAdena();}if(gap(origin,location(p))>100)departed=true;if(goal!=null&&gap(location(p),goal)<=650&&AutofarmManager.INSTANCE.isAutoFarming(p))arrived=true;if(AutofarmManager.INSTANCE.isAutoFarming(p))suspendValue(AutofarmManager.INSTANCE,"onUpdate",p);if(System.currentTimeMillis()-reported>=20000){reported=System.currentTimeMillis();System.out.println("BASE CLASS INFO seconds="+(reported-started)/1000+" at="+location(p)+" goal="+goal+" cash="+p.getAdena()+" hp="+(int)p.getCurrentHp()+" xp="+p.getExp()+" paid="+paid+" arrived="+arrived);}Thread.sleep(300);}
  check(departed&&paid&&arrived&&!p.isDead()&&p.getExp()>xp,"observed owner pays a real fare, physically reaches prey and earns ordinary experience");check(p.getInventory().getInventoryItemCount(736,-1)==scroll&&!p.isGM()&&!p.isInvul(),"route uses no escape scroll, GM protection or free resources");System.out.println("BASE CLASS RESULT xp="+xp+"->"+p.getExp()+" cash="+cash+"->"+p.getAdena()+" actualFare="+actualFare+" seconds="+(System.currentTimeMillis()-started)/1000);farmers.remove(p.getObjectId());invoke(AutofarmManager.INSTANCE,"quiesce",p);
  // Separate controlled policy checks: already promoted characters retain the normal reserve.
  Player other=Player.restore(268491948);check(other!=null,"secondary policy actor restores");other.setClassId(44);other.getStat().setLevel((byte)20);supplies(other,10);money(other,2205);check((Integer)invoke(errands,"travelSpendable",other)==2205,"other base-class actor receives the same prepared policy");other.setClassId(45);check((Integer)invoke(errands,"travelSpendable",other)==5,"first profession restores the usual monetary reserve");other.setClassId(44);supplies(other,2);check((Integer)invoke(errands,"travelSpendable",other)==5,"insufficient carried healing cannot unlock reserve spending");supplies(other,10);erase(other,736);check((Integer)invoke(errands,"travelSpendable",other)==5,"missing owned escape scroll cannot unlock reserve spending");System.out.println("BASE CLASS TRAVEL BUDGET ALL PASSED");System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
